import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Check if we have enough patients and features
    if len(feats.ids) < 2 or feats.n < 10:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Look for strong univariate associations
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'cohort':
            # Skip clinical/cohort variables for driver detection
            continue
        # Compute effect size (difference in means between outcome groups)
        y0 = feats.x[feats.y == 0, i]
        y1 = feats.x[feats.y == 1, i]
        if len(y0) > 0 and len(y1) > 0:
            effect = np.mean(y1) - np.mean(y0)
            t_stat, p_val = stats.ttest_ind(y1, y0, equal_var=False)
            auc = 0.5 + 0.5 * (np.mean(y1) - np.mean(y0)) / np.std(np.concatenate([y0, y1]))
            effects.append((abs(effect), fid, abs(t_stat), p_val, auc))

    # Sort by effect size and p-value
    effects.sort(reverse=True)

    # Find drivers (strongest features that might be causal)
    drivers = []
    for _, fid, _, p_val, _ in effects:
        if len(drivers) >= MAX_DRIVERS:
            break
        if p_val < 0.05:
            drivers.append(fid)

    # If no strong drivers found, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build set of columns to include in model
    columns = list(drivers)
    # Add other significant features
    for _, fid, _, p_val, _ in effects[:10]:  # Top 10 additional features
        if fid not in columns and p_val < 0.1:
            columns.append(fid)

    # Check for interactions
    products = []
    for i, a in enumerate(columns):
        for b in columns[i+1:]:
            # Check correlation to avoid near-duplicates
            idx_a = feats.column(a)
            idx_b = feats.column(b)
            corr = np.corrcoef(feats.x[:, idx_a], feats.x[:, idx_b])[0, 1]
            if abs(corr) < 0.6:
                products.append((a, b))

    # Weighted score based on mutual information
    loadings = {}
    for fid in columns:
        idx = feats.column(fid)
        mi = mutual_info_classif(feats.x[:, [idx]], feats.y)[0]
        loadings[fid] = mi

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)

